#!/usr/bin/env python3
"""R23 cumulative T1 counter; original R22 binding policy is reused unchanged.

Two fixed evidence roots, one frozen six-verb denominator. New witnesses also
need an S058+ mined A/B row opened2026-10-21 with the exact entry in used-by.
Historical witnesses are measured at the frozen baseline, never extended by
new files under the old root. New entries are scanned explicitly and use the
reviewed original-envelope binder. Source relevance/admission remain manual.
0=clean6/6;1=failed/incomplete;2=could-not-evaluate. No authentication claim.
"""
import argparse
import hashlib
import types
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

LEGACY = '.ufo/waves/round-22/tools/count-c1.py'
LEGACY_SHA256 = 'c925918fb871151f86065aa5b3e9d10334ab845ed67c265ae0977f05e09b1879'
ROOTS = ('.ufo/waves/round-22/evidence/c1/', '.ufo/waves/round-23/evidence/c1/')
SELFTEST_MANIFEST_SHA256 = '458b30d5a6420c1b37874c3364d3ae3b22529d6c3560b5241848a21eec97096f'
BASELINE = 'aa1450b82f9ede35aada63efe8a34e01c6e02f72'
CATALOG = '.ufo/waves/round-20/verify/round20/verb-coverage.json'

def git(root, *args):
    p = subprocess.run(['git', '-C', str(root), *args], capture_output=True, check=False)
    if p.returncode:
        raise ValueError('git_input_unreadable')
    return p.stdout


def load(path, name):
    module = types.ModuleType(name)
    module.__file__ = str(path)
    exec(compile(path.read_bytes(), str(path), 'exec'), module.__dict__)
    return module

def bind_new(r22, r21, text, verb, evidence_id):
    # Keep refusal ancestry in metadata/sibling containers as well as data.
    try:
        pending = [r21.decode(text)]
        while pending:
            node = pending.pop()
            if isinstance(node, list):
                pending.extend(node)
            elif isinstance(node, dict):
                if ('ok' in node and node['ok'] is not True) or r21.refused(node):
                    return 1
                pending.extend(node.values())
        return r22.bind_cli(r21, text, verb, evidence_id)
    except (ValueError, RecursionError):
        return 2


def measure(root, revision):
    rev = git(root, 'rev-parse', '--verify', '--end-of-options', revision+'^{commit}').decode().strip()
    legacy = git(root, 'show', rev+':'+LEGACY)
    if hashlib.sha256(legacy).hexdigest() != LEGACY_SHA256:
        raise ValueError('legacy_source_untrusted')
    if git(root, 'show', rev+':'+CATALOG) != git(root, 'show', BASELINE+':'+CATALOG):
        raise ValueError('catalog_changed')
    old_root = ROOTS[0].rstrip('/')
    if git(root, 'rev-parse', rev+':'+old_root) != git(root, 'rev-parse', BASELINE+':'+old_root):
        raise ValueError('historical_evidence_changed')
    old_sources = git(root, 'show', BASELINE+':corpus/SOURCES.md').decode('utf-8')
    new_sources = git(root, 'show', rev+':corpus/SOURCES.md').decode('utf-8')
    source_rows = lambda text: [line for line in text.splitlines() if re.match(r'^\| S[0-9]+ \|', line)]
    if source_rows(new_sources)[:len(source_rows(old_sources))] != source_rows(old_sources):
        raise ValueError('historical_sources_changed')
    runtime = root / '.ufo/waves/round-23/runtime'
    runtime.mkdir(parents=True, exist_ok=True)
    tempfile.tempdir = str(runtime)
    with tempfile.TemporaryDirectory(prefix='counter-') as directory:
        path = Path(directory) / 'r22.py'
        path.write_bytes(legacy)
        r22 = load(path, 'reviewed_r22_counter')
        historical = r22.measure(root, BASELINE)
        if historical['t1_exercised'] != ['identify-flutter-build']:
            raise ValueError('historical_baseline_changed')
        r21, r20 = r22.revision_helpers(root, rev)
    rows = {}
    for line in git(root, 'show', rev+':corpus/SOURCES.md').decode('utf-8').splitlines():
        cells = [c.strip() for c in line.split('|')]
        if len(cells) == 13 and re.fullmatch(r'S[0-9]{3,}', cells[1]):
            if cells[1] in rows:
                raise ValueError('duplicate_source_id')
            rows[cells[1]] = cells
    targets = {verb: {'historical': historical['targets'][verb]['bound_evidence'], 'new': []}
               for verb in r22.T1}
    files = git(root, 'ls-tree', '-r', '--name-only', rev, '--', 'corpus/knowledge/').decode('utf-8').splitlines()
    catalog = r21.decode(git(root, 'show', rev+':'+CATALOG).decode('utf-8'))['cli_commands']
    mentioned = set()
    cited_pattern = re.compile(r'(?<![/A-Za-z0-9_.-])'+re.escape(ROOTS[1])+r'[A-Za-z0-9._/-]+')
    for entry in files:
        text = git(root, 'show', rev+':'+entry).decode('utf-8')
        mentioned.update(verb for verb in catalog if r20.command_pattern(verb).search(text))
        first = text.partition('\n')[0]
        if not first.startswith('source:'):
            continue
        eligible = False
        for sid in re.findall(r'\bS[0-9]{3,}\b', first):
            row = rows.get(sid)
            if row and int(sid[1:]) >= 58 and row[4] in ('A', 'B') and row[8] == 'mined' and row[9] == '2026-10-21' and entry in [x.strip() for x in row[11].split(',')]:
                eligible = True
        if not eligible:
            continue
        ids = sorted(set(r20.HEX64.findall(text)))
        for evidence_path in sorted(set(cited_pattern.findall(text))):
            if not evidence_path.endswith('.json'):
                continue  # Carrier bytes are cited provenance, not JSON Evidence.
            # Git fails closed on missing/absolute/traversal citations; no live path reads.
            if '..' in evidence_path.split('/'):
                raise ValueError('evidence_path_invalid')
            blob = git(root, 'show', rev+':'+evidence_path).decode('utf-8')
            for verb in r22.T1:
                if not r20.command_pattern(verb).search(text):
                    continue
                for eid in ids:
                    if eid in blob and bind_new(r22, r21, blob, verb, eid) == 0:
                        targets[verb]['new'].append({'entry': entry, 'evidence_id': eid, 'path': evidence_path})
    for target in targets.values():
        target['exercised'] = bool(target['historical'] or target['new'])
    held = [verb for verb in r22.T1 if targets[verb]['exercised']]
    return {'rev': rev, 'historical_rev': BASELINE, 'claim': 'R23-C1',
            'finding': 'c1_complete' if len(held)==6 else 'c1_incomplete',
            't1': list(r22.T1), 't1_exercised': held, 't1_exercised_count': len(held), 't1_total': 6,
            'targets': targets, 'catalog_mentioned_count': len(mentioned),
            'catalog_total': len(catalog), 'catalog_zero_count': len(catalog)-len(mentioned),
            'limit': 'local original-envelope/source linkage; run stdout checked separately; manual source relevance; no authentication'}


def selftest(root):
    frozen = root / '.ufo/waves/round-23/frozen'
    raw = (frozen/'expected-v2.json').read_bytes()
    if hashlib.sha256(raw).hexdigest() != SELFTEST_MANIFEST_SHA256:
        raise ValueError('snapshot_tampered: manifest')
    manifest = json.loads(raw)
    for rel, digest in manifest['inputs'].items():
        if hashlib.sha256((root/rel).read_bytes()).hexdigest() != digest:
            raise ValueError('snapshot_tampered: '+rel)
    fixtures = load(root / '.ufo/waves/round-23/tools/counter-fixtures.py', 'r23_independent_fixtures')
    return fixtures.run(root, Path(__file__).resolve(), manifest)


def main():
    for key in tuple(os.environ):
        if key.startswith('GIT_'):
            del os.environ[key]
    os.environ['GIT_NO_REPLACE_OBJECTS'] = '1'
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--root', type=Path, required=True)
    p.add_argument('--rev')
    p.add_argument('--selftest', action='store_true')
    a = p.parse_args()
    try:
        if a.selftest:
            result, code = selftest(a.root.resolve())
        else:
            if not a.rev:
                raise ValueError('revision_required')
            result = measure(a.root.resolve(), a.rev)
            code = 0 if result['t1_exercised_count'] == 6 else 1
    except (OSError, ValueError, UnicodeError, RecursionError, KeyError) as error:
        result, code = {'finding': 'unevaluable', 'error': str(error)}, 2
    print(json.dumps(result, sort_keys=True))
    return code

if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Independent synthetic fixtures: no validator fixture builder or decision import.

All Git writes are confined to disposable clones under the lane runtime root.
Synthetic minimal envelopes are control inputs, never producer Evidence claims.
"""
import copy
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile

PREFIX = '.ufo/waves/round-23/evidence/c1/'
ENTRY = 'corpus/knowledge/control-r23-synthetic.md'


def run(root, counter, manifest):
    results = []
    runtime = root / '.ufo/waves/round-23/runtime'
    runtime.mkdir(parents=True, exist_ok=True)
    fixture = json.loads((root/'.ufo/waves/round-23/frozen/fixture.json').read_text())
    def command(argv, cwd):
        p = subprocess.run(argv, cwd=cwd, capture_output=True, text=True, check=False)
        if p.returncode:
            raise RuntimeError(p.stderr)
        return p.stdout
    with tempfile.TemporaryDirectory(prefix='fixture-', dir=runtime) as directory:
        repo = Path(directory)/'repo'
        command(['git', 'clone', '--shared', '--no-checkout', str(root), str(repo)], root)
        command(['git', 'checkout', fixture['base']], repo)
        for name, expected in manifest['cases'].items():
            # Reset only this disposable clone, never the lane checkout/index.
            command(['git', 'reset', '--hard', fixture['base']], repo)
            command(['git', 'clean', '-fd'], repo)
            documents = copy.deepcopy(fixture['documents'])
            selected = ['inspect-signal-decoders']
            if name == 'all_six':
                selected = list(documents)
            if name == 'same_verb':
                selected = ['identify-flutter-build']
            if name == 'mention_only':
                selected = []
            evidence = repo / PREFIX
            evidence.mkdir(parents=True, exist_ok=True)
            text = 'source: S058 synthetic isolated control\nverified-at: fixture\nrecheck: selftest\n\n'
            for verb in selected:
                envelope = documents[verb]
                if name == 'refused_parent':
                    envelope['ok'] = False
                elif name == 'nested_refusal':
                    envelope['data']['normalized_result'] = {'errors': ['execution_failure']}
                elif name == 'wrong_command':
                    envelope['meta']['command'] = 'identify-flutter-build'
                elif name == 'wrong_operation':
                    envelope['data']['operation'] = 'identify_flutter_build'
                elif name == 'meta_false':
                    envelope['meta']['ok'] = False
                elif name == 'meta_array':
                    envelope['meta']['raw_result'] = [{'ok': False}]
                elif name == 'sibling_refusal':
                    envelope['result'] = {'errors': ['execution_failure']}
                eid = envelope['data']['evidence_id']
                path = PREFIX+verb+'.json'
                raw = json.dumps(envelope)
                if name == 'duplicate_member':
                    raw = raw.replace('"ok": true', '"ok": false, "ok": true')
                (repo/path).write_text(raw+'\n')
                text += verb+' '+eid+' '+path+'\n'
            if name == 'absolute_citation':
                text = text.replace(PREFIX, '/tmp/not-the-lane/'+PREFIX)
            if name == 'mention_only':
                text += 'inspect-signal-decoders ev_'+'a'*64+'\n'
            if name == 'missing_source':
                text = text.replace('source: S058 synthetic isolated control', 'source: none')
            if name == 'old_source':
                text = text.replace('source: S058', 'source: S051')
            (repo/ENTRY).write_text(text)
            source = repo/'corpus/SOURCES.md'
            body = source.read_text()
            usedby = 'corpus/knowledge/not-this-entry.md' if name == 'wrong_usedby' else ENTRY
            row = '| S058 | isolated control | own-work | A | synthetic control only | fixture | control, not real Evidence | mined | 2026-10-21 | on-release | '+usedby+' |\n'
            body = body.replace('\n## Paths', '\n'+row+'\n## Paths', 1)
            if name == 'old_source':
                body = '\n'.join(line.rstrip().rstrip('|')+', '+ENTRY+' |' if line.startswith('| S051 |') else line for line in body.splitlines())+'\n'
            source.write_text(body)
            if name == 'helper_tamper':
                p = repo/'.ufo/waves/round-22/tools/count-c1.py'
                p.write_text(p.read_text()+'\n# changed control\n')
            if name == 'invalid_utf8':
                (evidence/'inspect-signal-decoders.json').write_bytes(b'\xff')
            if name == 'historical_root_injection':
                (repo/'.ufo/waves/round-22/evidence/c1/new-control.json').write_text('{}')
            if name == 'inherited_lost':
                (repo/'.ufo/waves/round-22/evidence/c1/identify-godot.envelope.json').unlink()
            if name == 'catalog_changed':
                p = repo/'.ufo/waves/round-20/verify/round20/verb-coverage.json'
                p.write_text(p.read_text()+'\n')
            command(['git', 'add', '--', ENTRY, 'corpus/SOURCES.md', PREFIX,
                     '.ufo/waves/round-22/tools/count-c1.py', '.ufo/waves/round-22/evidence/c1',
                     '.ufo/waves/round-20/verify/round20/verb-coverage.json'], repo)
            command(['git', '-c', 'user.name=isolated-fixture', '-c', 'user.email=fixture@invalid', 'commit', '-m', 'synthetic counter control'], repo)
            revision = command(['git', 'rev-parse', 'HEAD'], repo).strip()
            argv = [sys.executable, '-I', '-B', str(counter), '--root', str(repo), '--rev', revision]
            p = subprocess.run(argv, capture_output=True, text=True, check=False)
            try:
                out = json.loads(p.stdout)
            except ValueError:
                out = {}
            observed = {'exit': p.returncode, 'count': out.get('t1_exercised_count'), 'finding': out.get('finding')}
            passed = all(observed.get(key) == value for key, value in expected.items())
            results.append({'case': name, 'expected': expected, 'observed': observed, 'passed': passed,
                            'argv': argv, 'stdout': p.stdout, 'stderr': p.stderr})
    return {'finding': 'selftest_clean' if all(x['passed'] for x in results) else 'selftest_failed',
            'passed': sum(x['passed'] for x in results), 'total': len(results), 'cases': results}, 0 if all(x['passed'] for x in results) else 1

